import {magpieScenes,magpieLessons,magpieSortCards,magpieArtDescriptions,magpieCopy as T} from './magpie-pictures-content.mjs';
import {changeMagpiePictures,magpiePicturesModel,magpiePicturesNarration} from './magpie-pictures-core.mjs';

const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['party','Party pictures'],['learn','See why'],['sort','Sort the sayings']];
const trays={literal:'Words used literally here',figurative:'Words used figuratively here'};
const button=(action,label,value='',extra='',inside='')=>`<button type="button" class="magpie-button" data-magpie-action="${action}" data-magpie-value="${esc(value)}" ${extra}>${inside}<span>${esc(label)}</span></button>`;

// Original cut-paper actors and props. No SVG text, internal IDs or borrowed images.
const group=(x,y,scale,body)=>`<g transform="translate(${x} ${y}) scale(${scale})">${body}</g>`;
function pip(x,y,s=1,gesture=false){return group(x,y,s,`<path d="M35 70Q-3 90 7 48Q13 64 35 54" fill="#cd7947"/><path d="M7 48Q10 65 20 66L13 78Q4 73 7 48" fill="#fff8df"/><path d="M28 42Q12 70 31 84h30Q79 67 61 42" fill="#cd7947"/><path d="m29 77-3 13h15l3-12m10-1 2 13h15l-6-14" fill="#614331"/><path d="M24 16 23-6 40 7Q50 4 60 7L76-6 74 23 58 46H40Z" fill="#df9053"/><path d="m26 1 4 16 9-7m23 0 9-10-3 18" fill="#d9b8a0"/><path d="M25 24 44 26 50 37 57 26 74 24 59 46H40Z" fill="#fff6df"/><path d="m46 34 8 0-4 6Z" fill="#303d3e"/><circle cx="38" cy="21" r="2.3" fill="#303d3e"/><circle cx="62" cy="21" r="2.3" fill="#303d3e"/><path d="M45 42q5 5 10 0" fill="none"/>${gesture?'<path d="M31 55 20 44m40 13 17-17" fill="none"/>':'<path d="m30 56-8 11m41-11 8 11" fill="none"/>'}`);}
function dot(x,y,s=1,wave=false){return group(x,y,s,`<path d="m22 56-12 8m11 6-12 9m52-23 12 8m-12 6 12 9m-48 5-4 9m32-9 4 9" fill="none"/><ellipse cx="42" cy="60" rx="30" ry="30" fill="#ce796b"/><path d="M42 34v53" fill="none"/><g fill="#344746"><circle cx="26" cy="51" r="5"/><circle cx="57" cy="51" r="5"/><circle cx="26" cy="72" r="5"/><circle cx="57" cy="72" r="5"/></g><path d="m31 9-6-10m27 10 6-10" fill="none"/><circle cx="42" cy="21" r="20" fill="#344746"/><ellipse cx="35" cy="19" rx="4" ry="5" fill="#fff8e8"/><ellipse cx="49" cy="19" rx="4" ry="5" fill="#fff8e8"/><path d="M36 30q6 5 12 0" fill="none" stroke="#fff8e8"/>${wave?'<path d="M17 42 6 23 9 17m-3 6-6-3" fill="none"/>':''}`);}
function ember(x,y,s=1,nervous=false){return group(x,y,s,`<path d="M24 62Q-12 78-3 43L14 52" fill="#76a99d"/><path d="M50 48 80 25 76 62 57 72" fill="#a7c5ac"/><path d="m57 52 19 10-4-19" fill="none"/><path d="M28 38Q8 67 24 87h39Q80 68 56 38" fill="#76a99d"/><ellipse cx="44" cy="67" rx="14" ry="19" fill="#ead7a3"/><path d="m25 80-8 13h21l4-12m13-1 3 13h19L64 79" fill="#76a99d"/><path d="m25 11 3-15 11 12m10 0 11-12 5 21" fill="#e4be68"/><path d="M25 9Q14 17 24 31L11 37q-3 15 26 16Q64 52 64 27 64 7 47 7Z" fill="#76a99d"/><circle cx="40" cy="24" r="2.5" fill="#303d3e"/><circle cx="19" cy="41" r="1.5" fill="#303d3e"/><path d="${nervous?'M30 43q7-5 12 0M34 17l9 3':'M27 43q8 7 16 0'}" fill="none"/>`);}
function magpie(x,y,s=1){return group(x,y,s,'<path d="m35 53-30 34 11-38" fill="#396c72"/><ellipse cx="40" cy="43" rx="23" ry="29" fill="#303d3e"/><path d="M20 36q7 32 28 29L52 38" fill="#fff9e9"/><path d="M39 31q29 8 19 32Q37 57 39 31" fill="#396c72"/><circle cx="39" cy="13" r="18" fill="#303d3e"/><path d="m24 10-15 8 17 2" fill="#d8ae5b"/><circle cx="34" cy="10" r="2.4" fill="#fff9e9"/><path d="m34 69-2 15m15-16 5 15m-25 0h11m10 0h11" fill="none"/>');}
const paper=(x,y,s=1)=>group(x,y,s,'<path d="M0 3 66 0 70 63 4 65Z" fill="#fffcf0"/><path d="M13 15h40M13 24h29M13 33h37M13 42h18" stroke="#8faaa3" fill="none"/>');
const note=(x,y,s=1)=>group(x,y,s,'<path d="M0 26V3l18-3v22M0 10l18-3" stroke="#626178" fill="none" stroke-width="4"/><ellipse cx="-4" cy="27" rx="5" ry="3" fill="#626178"/><ellipse cx="14" cy="23" rx="5" ry="3" fill="#626178"/>');
const butterfly=(x,y,s=1)=>group(x,y,s,'<path d="M0 8Q-18-10-14 7q1 8 13 8Q-14 31-3 25l3-9Q12 32 16 21q1-6-14-7Q24 5 12 0 6-1 0 8" fill="#d8ae5b"/><path d="M0 6v15" fill="none"/>');
const cat=(x,y,s=1)=>group(x,y,s,'<path d="M21 37Q-4 24 3 14q5-4 7 3" fill="none" stroke-width="5"/><ellipse cx="39" cy="39" rx="24" ry="17" fill="#d7b882"/><path d="m31 49 2 14h10l3-14m9-4 10 9h10" fill="none" stroke-width="5"/><path d="m32 8 2-16L47 4 61-8l2 24Q65 35 48 35 29 34 32 8" fill="#d7b882"/><circle cx="42" cy="15" r="1.7" fill="#303d3e"/><circle cx="55" cy="15" r="1.7" fill="#303d3e"/><path d="m45 23 5 0m-14-2-12-3m13 10-12 3m32-10 13-3m-13 10 12 3" fill="none"/>');
const dog=(x,y,s=1)=>group(x,y,s,'<path d="m18 36-9-13" fill="none" stroke-width="5"/><ellipse cx="34" cy="38" rx="22" ry="15" fill="#c29379"/><path d="m21 48-2 14h10m18-15 5 15h9" fill="none" stroke-width="5"/><path d="M42 6q-14 18 0 25l8-17m9-7q14-8 19 5l-7 18-8-11" fill="#86624e"/><path d="M43 9q9-15 22 0l4 10 9 4v10H54Q40 29 43 9" fill="#c29379"/><circle cx="58" cy="15" r="1.8" fill="#303d3e"/><path d="m72 23 5 0m-20 4q3 5 8 1" fill="none"/>');
const umbrella=(x,y,color)=>group(x,y,1,`<path d="M-31 0q31-43 62 0-9-5-15 0-8-5-16 0-8-5-16 0-8-5-15 0" fill="${color}"/><path d="M0-22v57q0 11 8 6" fill="none"/>`);
const cake=(x,y,s=1)=>group(x,y,s,'<ellipse cx="50" cy="70" rx="64" ry="12" fill="#c7ded4"/><path d="m0 20 60-17 40 26v36L0 57Z" fill="#e4ba7b"/><path d="m0 20 60-17 40 26-68 16Z" fill="#fff1d0"/><path d="M0 37 32 60l68-15" stroke="#b96f77" stroke-width="7" fill="none"/><path d="m0 20 32 25 68-16v8L32 53 0 29Z" fill="#f8e6d2"/><circle cx="58" cy="12" r="7" fill="#c47777"/>');
const bag=(x,y,s=1)=>group(x,y,s,'<path d="M0 15 17 0h61l17 17-5 72H5Z" fill="#d9b98b"/><path d="m0 15 40 10 55-8-17-17H17Z" fill="#80634d"/><path d="m5 81 16-13m65 12L75 67M40 25l2 52" fill="none" stroke="#ac8c63"/>');
const table='<path d="M118 142h161v12H118Zm15 12-4 45m134-45 6 45" fill="#b98d68"/>';
const floor='<ellipse cx="161" cy="198" rx="128" ry="9" fill="#d7c8a5" stroke="none" opacity=".6"/>';
const windowFrame='<path d="M26 20h268v158H26Z" fill="#d9e6e1"/><path d="M32 26h256v145H32Z" fill="#e9eee6"/><path d="M160 27v144M32 98h256M20 179h280" fill="none" stroke="#967c63" stroke-width="7"/>';
const art={
 hungry:()=>`${pip(23,100,.95,true)}${table}<ellipse cx="173" cy="140" rx="34" ry="9" fill="#fff9e8"/><ellipse cx="173" cy="140" rx="23" ry="5" fill="none"/><path d="M206 113q25 36 50 0Z" fill="#7dafa7"/><ellipse cx="231" cy="113" rx="25" ry="6" fill="#deb66e"/><path d="M228 98q-8-7 0-16m12 17q-8-7 0-16" fill="none" stroke="#a4b5a5"/><path d="M268 139q-9-21 7-24 20-1 16 24Z" fill="#ddb17a"/><path d="m271 121 2 7m7-8 2 7" fill="none"/>`,
 'horse-plate':()=>`<path d="m43 44 10 7m203-10 9-6m-6 24 10 2" fill="none" stroke="#b3a3b6"/><ellipse cx="158" cy="177" rx="127" ry="25" fill="#f7f1df"/><ellipse cx="158" cy="177" rx="109" ry="17" fill="none" stroke="#b0c5bc"/><path d="M91 114q-24-28-36 9" fill="none" stroke="#77553e" stroke-width="9"/><path d="M88 83q12-20 63-8l32 8 8-40 32 3-8 61-24 19H95Z" fill="#c5976a"/><path d="M96 117v55h15l8-53m45 3 7 50h15l-2-51" fill="#c5976a"/><path d="m193 47 2-20 12 18 12-20 6 22 15 24q6 17-15 20l-32-12" fill="#c5976a"/><path d="M187 47 181 81" stroke="#77553e" stroke-width="8"/><circle cx="214" cy="57" r="3" fill="#303d3e"/><path d="M217 78q9 5 15-2" fill="none"/>`,
 'horse-ride':()=>`${pip(27,101,1)}<path d="m204 98 7 90" fill="none" stroke="#a37b50" stroke-width="10"/><path d="m191 89 3-35 15 12 16-15 6 22 20 15-7 15-30-4-15 18-22-11Z" fill="#d1a574"/><path d="m193 54-8 22 11 4-13 17" fill="none" stroke="#6f5844" stroke-width="7"/><circle cx="216" cy="76" r="2.7" fill="#303d3e"/><path d="m203 99 24 12-12 14-23-13Z" fill="#728e8d"/><path d="m180 194 67-4" stroke="#a37b50" stroke-width="6"/>`,
 'ice-bowl':()=>`<ellipse cx="159" cy="181" rx="112" ry="15" fill="#c8d7c9"/><path d="M54 105q8 82 106 82 98 0 108-82Z" fill="#a9c8bf"/><ellipse cx="161" cy="105" rx="107" ry="23" fill="#ece6aa"/><path d="m118 81 38-17 41 18-3 46-47 8-32-23Z" fill="#def0eb"/><path d="m156 64-10 22 14 11-13 39m-29-55 28 5 51-4" fill="none" stroke="#6d999c"/><path d="m212 20-42 62q-7 10 1 17 10 8 18-5l43-64q6-13-5-17-8-3-15 7Z" fill="#bb9168"/><path d="m94 52-9-10m19-2-3-13m95 20 11-6" fill="none" stroke="#bca362"/><circle cx="80" cy="107" r="9" fill="#eee8ab"/>`,
 greeting:()=>`${table}${pip(177,64,.65)}${ember(235,64,.65)}${dot(43,97,1,true)}<path d="M138 28h53q12 0 12 12v15q0 11-12 11h-13l-9 10V66h-31q-11 0-11-11V40q0-12 11-12Z" fill="#fffcf0"/><path d="M227 22h49q12 0 12 12v15q0 11-12 11h-23l-9 10V60h-17q-11 0-11-11V34q0-12 11-12Z" fill="#fffcf0"/>`,
 leaving:()=>`<path d="M208 29h81v164h-81Z" fill="#b89670"/><path d="M220 42h57v151h-57Z" fill="#e7e3ca"/><path d="m277 43-39 13v137h39Z" fill="#7c9b90"/><circle cx="249" cy="126" r="4" fill="#e2c37e"/>${dot(95,101,.95)}<path d="m164 107 19-9 17 18-10 14-10-7 3 60h-45l10-62-10 10-12-13 21-20Z" fill="#9e9db7"/><path d="m161 102 6 19 13-21" fill="none"/>`,
 'butterfly-outline':()=>`<path d="m58 23 210 6-11 172-211-9Z" fill="#fffcef"/><path d="m75 14 22 6-7 17-22-7m176 148 23 4-4 21-24-4" fill="#d2bd88" stroke="none"/><g transform="translate(94 53) scale(1.25)" fill="none" stroke="#8d9d91" stroke-dasharray="5 4"><path d="M29 44-4 62l11-29 22 7M61 47 89 23l-3 40-23 14M27 42Q11 61 26 85h37Q82 61 58 41M25 11 27-3 40 9m11 0L63-3l2 24M25 10Q14 18 24 32L11 38q-3 15 26 16Q65 52 65 27 65 8 47 8"/></g>${butterfly(144,128,.68)}${butterfly(162,145,.5)}${magpie(244,147,.52)}`,
 'butterfly-garden':()=>`${ember(30,91,1.03)}${butterfly(191,59,1)}${butterfly(259,87,.75)}<path d="M178 186v-39m58 39v-27m43 27v-51" stroke="#719b77" fill="none"/>${[ [178,141],[236,153],[279,129] ].map(([x,y])=>group(x,y,1,'<path d="M0-11Q15-20 11-5 29 4 12 8 12 27 0 12-14 27-13 8-29 4-12-5-16-21 0-11Z" fill="#d9a188"/><circle r="6" fill="#dfc276"/>')).join('')}`,
 'nervous-speech':()=>`${ember(32,91,1.1,true)}${paper(86,132,.54)}<path d="m59 151 25-11m34 13-10-13" fill="none" stroke-width="5" stroke="#5d897f"/><path d="M190 109h88l-13 24h-63Zm14 25h60v55h-60Z" fill="#bc956e"/><path d="M218 110V85q0-15 15-15" fill="none"/><circle cx="236" cy="69" r="5" fill="#344746"/><path d="m64 69-7-11m21 5-1-13m54 40 10-7" fill="none" stroke="#a49bb0"/>`,
 'cat-bag':()=>`${bag(44,88,1.15)}${cat(127,104,1.2)}<path d="m210 182 15 0m-8-14 10 5" fill="none" stroke="#baac85"/>`,
 'song-news':()=>`<path d="M107 32q56 10 111 0v72q-59 12-111 0Z" fill="#c7dcd0"/><path d="m107 32-10-4v90m121-86 9-4v90" fill="none" stroke="#a68058"/>${note(132,52,.8)}${note(183,58,.8)}${pip(28,103,.95,true)}${ember(226,102,.96)}`,
 'mend-bag':()=>`${pip(27,101,.95)}${bag(176,87,1.12)}<path d="m192 127 14 5-10 13 17 7-8 16" fill="none"/><path d="m185 134 42-4 4 36-41 4Z" fill="#f3dfaf"/><path d="m197 141 22-2m-21 12 22-2m-20 12 22-2" stroke="#bc986b" fill="none"/><path d="m95 159 73-12" fill="none"/><path d="m161 144 14-1 1 11-14 1Z" fill="#f3dfaf"/>`,
 'easy-riddle':()=>`${dot(35,97,1.02)}${table}${paper(170,62,1.2)}<path d="M188 134h70" fill="none" stroke="#c1ac80"/>`,
 'riddle-cake':()=>`${cake(97,112,1.25)}${paper(117,62,1.05)}<path d="m62 57 8 3m183-10 8-5m-4 35 10 2" fill="none" stroke="#afa0b6"/>`,
 'icing-card':()=>`${magpie(47,94,1.1)}${table}${paper(163,93,1.05)}<path d="M191 117q35-7 30 14-8 17-27 5-10-10 4-14 11-2 10 7" fill="none" stroke="#cb9bb1" stroke-width="5"/><path d="m115 135 57-19" fill="none" stroke="#a67a51" stroke-width="5"/><path d="m169 113 7 4-7 4" fill="#cb9bb1"/>`,
 'light-rain':()=>`${windowFrame}<path d="m77 52-5 12m133 62-5 12m43-89-5 12" fill="none" stroke="#7ea6b4" stroke-width="4"/><path d="M34 158q59-8 124 0t129 0" stroke="#b4c7b3" fill="none"/>`,
 'rain-animals':()=>`<path d="M68 54Q41 52 52 32q-1-20 20-18 18-23 38-7 25-6 34 15 24 1 20 21-2 19-30 15Z" fill="#d8e2e1"/>${umbrella(100,94,'#dfbb72')}${cat(67,130,.67)}${umbrella(235,71,'#93b6ac')}${dog(203,109,.7)}<path d="m45 119-4 11m129-54-4 11m-1 74-4 11m124-37-4 11" stroke="#88a8b2" fill="none"/>`,
 'heavy-rain':()=>`${windowFrame}<path d="${Array.from({length:17},(_,i)=>{const x=49+(i%8)*31,y=39+Math.floor(i/8)*43;return `M${x} ${y}l-10 24`;}).join(' ')}" fill="none" stroke="#6f98a6" stroke-width="4"/><ellipse cx="101" cy="157" rx="57" ry="9" fill="#a8c4cb"/><ellipse cx="231" cy="158" rx="48" ry="8" fill="#a8c4cb"/>${pip(40,145,.54)}${dot(226,145,.5)}`,
 'cake-slice':()=>`${cake(92,88,1.35)}<path d="m65 128-9 57m-8-70-4 17 20 4 4-17m-14-3-4 17" fill="none" stroke="#829c99" stroke-width="4"/>`
};
function picture(id,decorative=false,caption=null){
 const description=magpieArtDescriptions[id],draw=art[id];
 if(!description||!draw)return '<p class="magpie-art-fallback">Picture unavailable.</p>';
 const svg=`<svg class="magpie-art" data-magpie-art="${esc(id)}" viewBox="0 0 320 220" ${decorative?'aria-hidden="true"':`role="img" aria-label="${esc(description)}"`} focusable="false"><rect x="1" y="1" width="318" height="218" rx="20" fill="#f7efd9"/><g stroke="#344746" stroke-width="2.3" stroke-linejoin="round" stroke-linecap="round">${floor}${draw()}</g></svg>`;
 return decorative?svg:`<figure class="magpie-figure">${svg}<figcaption>${esc(caption??description)}</figcaption></figure>`;
}
function navigation(action,index,items,label,id){return `<div class="magpie-case-navigation"><label for="${id}">${label}</label><select id="${id}" data-magpie-action="${action}">${items.map((item,i)=>`<option value="${i}"${i===index?' selected':''}>${esc(action==='sort'?`Sorting card ${i+1} of ${items.length}`:item.title)}</option>`).join('')}</select><nav class="magpie-turns" aria-label="${esc(label)} navigation">${button(action,'Previous',index-1,`data-magpie-direction="previous"${index===0?' disabled':''}`)}<span>${index+1} of ${items.length}</span>${button(action,'Next',index+1,`data-magpie-direction="next"${index===items.length-1?' disabled':''}`)}</nav></div>`;}
function party(work,m){const scene=m.scene,own=work.ideas[work.scene];return `${navigation('scene',work.scene,magpieScenes,'Choose a scene','magpie-scene')}<h3 id="magpie-scene-title" tabindex="-1">${esc(scene.title)}</h3><div class="magpie-context"><p>${esc(scene.context)}</p><blockquote>${esc(scene.quote)}</blockquote></div><div class="magpie-party-grid"><section class="magpie-bird" data-magpie-bird><h4>The magpie's word picture</h4>${picture(scene.bird)}</section><section class="magpie-idea" data-magpie-idea><h4 id="magpie-idea-title" tabindex="-1">Your idea</h4><div class="magpie-choices">${scene.choices.map((choice,i)=>button('idea',choice.text,i,`aria-pressed="${own===i}"`,picture(choice.image,true))).join('')}</div><div class="magpie-actions">${button('idea','Not sure yet','unsure',`aria-pressed="${own==='unsure'}"`)}${button('clear-idea','Clear my idea','',own===null?'disabled':'')}</div>${own!==null?`<p class="magpie-own" data-magpie-own>${esc(own==='unsure'?T.uncertainty:scene.choices[own].text)}</p>`:''}</section></div><div class="magpie-actions">${button('reference',m.reference?'Hide this reading':'Show a reading of this scene','',`aria-expanded="${!!m.reference}"`)}</div>${m.reference?`<section class="magpie-reference" data-magpie-reference><h4>A reading of this scene</h4><div class="magpie-reference-grid">${picture(m.reference.image,false,m.reference.text)}<p><strong>Clue:</strong> ${esc(m.reference.clue)}</p></div></section>`:''}`;}
function learn(work,m){const lesson=m.lesson;return `${navigation('lesson',work.lesson,magpieLessons,'Choose a teaching card','magpie-lesson-select')}<h3 id="magpie-lesson" tabindex="-1">${esc(lesson.title)}</h3><p class="magpie-teaching">${esc(lesson.text)}</p><div class="magpie-lesson-pictures">${lesson.images.map(image=>picture(image)).join('')}</div>`;}
function sort(work,m){const card=m.sortCard,own=work.trays[work.sort];return `${navigation('sort',work.sort,magpieSortCards,'Choose a sorting card','magpie-sort-select')}<h3 id="magpie-sort-title" tabindex="-1">Sorting card ${work.sort+1} of ${magpieSortCards.length}</h3><div class="magpie-context"><p>${esc(card.context)}</p><blockquote>${esc(card.quote)}</blockquote></div><section class="magpie-trays" aria-label="Your tray">${Object.entries(trays).map(([value,label])=>button('tray',label,value,`aria-pressed="${own===value}"`)).join('')}</section>${own!==null?`<p class="magpie-own" data-magpie-own-tray>${esc(trays[own])}</p>`:''}<div class="magpie-actions">${button('clear-tray','Clear my tray','',own===null?'disabled':'')}${button('sort-reference',m.sortReference?'Hide this reading':'Show a reading of this card','',`aria-expanded="${!!m.sortReference}"`)}</div>${m.sortReference?`<section class="magpie-reference" data-magpie-sort-reference><h4>A reading of this card</h4><p>${esc(trays[m.sortReference.type])}</p>${picture(m.sortReference.image,false,m.sortReference.reason)}</section>`:''}`;}
export function magpiePicturesPage(work){const m=magpiePicturesModel(work),title=pages.find(([key])=>key===work.page)[1];return `<div class="magpie-page" data-magpie-root><header class="magpie-header"><div class="magpie-actions">${button('back','Back to Riddles')}<button type="button" class="magpie-button" data-magpie-hear data-speak="${esc(magpiePicturesNarration(work))}">Hear this page</button></div><h1 id="magpie-title" tabindex="-1">${esc(T.entryTitle)}</h1><p>${esc(T.intro)}</p></header><nav class="magpie-pages" aria-label="The magpie's pictures pages">${pages.map(([key,label])=>button('page',label,key,`aria-current="${work.page===key?'page':'false'}"`)).join('')}</nav><section class="magpie-sheet"><h2 id="magpie-page-title" tabindex="-1">${title}</h2>${work.page==='learn'?`<p>${esc(T.learnIntro)}</p>`:work.page==='sort'?`<p>${esc(T.sortIntro)}</p>`:''}${work.page==='party'?party(work,m):work.page==='learn'?learn(work,m):sort(work,m)}</section><footer class="magpie-lifetime"><p>${esc(T.lifetime)}</p></footer></div>`;}
export function bindMagpiePictures(work,ctx){
 const root=document.querySelector('[data-magpie-root]');if(!root)return;
 const valid=(n,e)=>{if(ctx.live(n)&&!n.disabled)return true;e.preventDefault();e.stopImmediatePropagation();return false;};
 const act=(n,e)=>{
  if(!valid(n,e))return;
  ctx.stopSpeech?.();ctx.stopSound?.();
  if(n.matches('[data-magpie-hear]')){n.dataset.speak=magpiePicturesNarration(work);return;}
  e.preventDefault();const action=n.dataset.magpieAction;
  if(action==='back'){ctx.back();return;}
  let value=n.matches('select')?n.value:n.dataset.magpieValue;
  if(['scene','lesson','sort'].includes(action)||action==='idea'&&value!=='unsure')value=Number(value);
  const next=changeMagpiePictures(work,action,value);if(next===work)return;
  ctx.change(next);ctx.render();
  let selector;
  if(action==='page')selector='#magpie-page-title';
  else if(['scene','lesson','sort'].includes(action)){
   const id={scene:'magpie-scene',lesson:'magpie-lesson-select',sort:'magpie-sort-select'}[action];
   const direction=n.dataset.magpieDirection;
   selector=direction?`[data-magpie-action="${action}"][data-magpie-direction="${direction}"]:not(:disabled)`:`#${id}`;
   if(!document.querySelector(selector))selector=`#${id}`;
  }else{
   selector=`[data-magpie-action="${action}"][data-magpie-value="${CSS.escape(n.dataset.magpieValue)}"]:not(:disabled)`;
   if(!document.querySelector(selector))selector=work.page==='sort'?'#magpie-sort-title':'#magpie-idea-title';
  }
  ctx.focus?.(selector);
 };
 // Capture precedes the shared local Hear listener, so stale controls never speak.
 root.querySelectorAll('button,select').forEach(n=>{
  n.addEventListener('click',e=>{if(n.matches('select')){valid(n,e);return;}act(n,e);},{capture:true});
  if(n.matches('select'))n.addEventListener('change',e=>act(n,e),{capture:true});
 });
}
